test('renders SVG matching reference', () => {
    const element = document.createElement('div');
    document.body.appendChild(element);

    const graph = new Rickshaw.Graph({
      element: element,
      width: 960,
      height: 500,
      renderer: 'scatterplot',
      series: [{
        color: 'steelblue',
        data: [
          { x: 0, y: 40 },
          { x: 1, y: 49 },
          { x: 2, y: 38 },
          { x: 3, y: 30 }
        ],
        strokeWidth: 5,
        opacity: 0.8
      }, {
        color: 'blue',
        data: [{ x: 4, y: 32 }]
      }]
    });

    graph.renderer.dotSize = 6;
    graph.render();

    const generatedSVG = element.innerHTML;
    const exampleSVG = fs.readFileSync(__dirname + '/data/simple.svg', 'utf8').trim();

    expect(generatedSVG).toBe(exampleSVG);
  })

test('creates both path and stroke elements', () => {
      const graph = createGraph({
        width: 10,
        height: 10,
        renderer: 'respectStrokeFactory',
        stroke: true,
        series: [{
          className: 'fnord',
          data: [
            { x: 0, y: 40 },
            { x: 1, y: 49 },
            { x: 2, y: 38 },
            { x: 3, y: 30 },
            { x: 4, y: 32 }
          ]
        }]
      });
      graph.render();

      const path = graph.vis.select('path.path.fnord');
      expect(path.size()).toBe(1);
      expect(path[0][0].getAttribute('opacity')).toBe('1');

      const stroke = graph.vis.select('path.stroke.fnord');
      expect(stroke.size()).toBe(1);

      // Check series references
      const firstSeries = graph.series[0];
      expect(d3.select(firstSeries.path).classed('path')).toBe(true);
      expect(d3.select(firstSeries.stroke).classed('stroke')).toBe(true);
    })

